// Everything you can build. Prices are in tokens (what Claude writes for you).
// size: [w, d] in tiles. unlock: lifetime tokens needed. pop: residents. jobs. joy: happiness nearby.
// build(b, r): draws the model centred on the origin, footprint w x d, using the Builder.
import * as THREE from 'three';
import { PAL, crown, pine } from './season.js';
export const C = {
  cream: '#f4e9d6', ivory: '#fbf5ea', terra: '#d9785a', clay: '#c9805f', sand: '#ead3ae', slate: '#7f879a', sage: '#a7c29a',
  moss: '#6f8f5f', leaf: PAL.snow ? '#e8edf0' : '#8fb072', leaf2: PAL.snow ? '#dde5e8' : '#6f9a5c', sky: '#9cc0dc', brick: '#c47b5e', char: '#4b4542', wood: '#9a6b47',
  roof: '#7d5d52', stone: '#ddd2c0', glass: '#b3cde0', gold: '#eab95e', white: '#ffffff', water: '#76bccd', pink: '#eca8b0',
  hedge: '#6e9459', lawn: PAL.snow ? '#eef1f2' : '#a9c787', paving: '#e3d7c4', butter: '#f3dfa6', mint: '#bcd8c0', rose: '#e9bfb0',
};
// roofs wear snow in winter
const roofC = (c) => (PAL.snow ? '#f1f4f6' : c);
const hash = (x, z, s) => { const v = Math.sin(x * 12.9898 + z * 78.233 + s * 37.719) * 43758.5453; return v - Math.floor(v); };

// one colour per tree, in three overlapping puffs, so a crown reads as a single soft shape
const tree = (b, x, z, s = 1, kind = 0) => {
  const h = hash(x, z, s);
  b.cyl(x, 0, z, 0.035 * s, 0.05 * s, 0.28 * s, C.wood, 6);
  if (kind === 0) { const c = crown(h); b.ball(x, 0.42 * s, z, 0.2 * s, c, { detail: 1 }); b.ball(x + 0.1 * s, 0.37 * s, z + 0.05 * s, 0.13 * s, c, { detail: 1 }); b.ball(x - 0.07 * s, 0.53 * s, z - 0.03 * s, 0.13 * s, c, { detail: 1 }); }
  else { const c = pine(h); b.cone(x, 0.18 * s, z, 0.2 * s, 0.4 * s, c, 7); b.cone(x, 0.36 * s, z, 0.15 * s, 0.34 * s, c, 7); b.cone(x, 0.53 * s, z, 0.1 * s, 0.26 * s, PAL.snow ? '#eef2f4' : c, 7); }
};
const door = (b, x, z, ry = 0, col = C.wood) => { b.box(x, 0, z, 0.18, 0.27, 0.025, C.ivory, { ry }); b.box(x, 0, z + 0.008, 0.13, 0.24, 0.03, col, { ry }); b.ball(x + 0.04, 0.12, z + 0.03, 0.008, C.gold); };
const glassDoors = (b, x, z, w = 0.42, h = 0.3) => { b.box(x, 0, z, w + 0.05, h + 0.04, 0.03, C.char); b.box(x - w / 4, 0.01, z + 0.012, w / 2 - 0.015, h, 0.012, C.glass); b.box(x + w / 4, 0.01, z + 0.012, w / 2 - 0.015, h, 0.012, C.glass); };
const lamp = (b, x, z) => { b.cyl(x, 0, z, 0.015, 0.02, 0.42, C.char, 5); b.ball(x, 0.45, z, 0.045, '#ffd894', { glow: true }); b.cone(x, 0.47, z, 0.06, 0.05, C.char, 6); b.mark('lamp', x, 0.45, z); };
const chimney = (b, x, y, z, h = 0.22) => { b.box(x, y, z, 0.08, h, 0.08, C.brick); b.box(x, y + h, z, 0.1, 0.03, 0.1, C.char); b.mark('smoke', x, y + h + 0.05, z); };
const flowerBox = (b, x, y, z, w = 0.22) => { b.box(x, y, z, w, 0.04, 0.05, C.wood); for (let i = 0; i < 4; i++) b.ball(x - w / 2 + w / 8 + i * w / 4, y + 0.055, z, 0.028, [C.pink, C.gold, C.terra, C.white][(i + Math.round(x * 10)) % 4]); };
const awning = (b, x, y, z, w, col) => { for (let i = 0; i < 5; i++) b.box(x - w / 2 + w / 10 + i * w / 5, y, z, w / 5, 0.05, 0.16, i % 2 ? C.ivory : col); };
const shrub = (b, x, z, s = 0.08) => b.ball(x, s * 0.8, z, s, PAL.snow ? '#e8eef0' : C.hedge, { detail: 1 });
const balcony = (b, x, y, z, w = 0.28) => { b.box(x, y, z, w, 0.02, 0.09, C.ivory); b.box(x, y + 0.02, z + 0.04, w, 0.06, 0.008, '#a8947f'); };
const columns = (b, x0, step, n, y, z, h, r = 0.045) => { for (let i = 0; i < n; i++) { b.cyl(x0 + i * step, y, z, r, r * 1.15, h, C.ivory, 8); b.box(x0 + i * step, y + h - 0.02, z, r * 2.6, 0.03, r * 2.6, C.stone); } };

