// A small airliner, nose towards +x, wheels on y.
export function planeParts(b, x, y, z, s = 1) {
  const white = '#f7f3ea', tail = C.terra;
  for (const [gx, gz] of [[0.42, 0], [-0.1, 0.12], [-0.1, -0.12]]) { b.box(x + gx * s, y, z + gz * s, 0.018 * s, 0.09 * s, 0.018 * s, C.char); b.cyl(x + gx * s, y, z + gz * s, 0.032 * s, 0.032 * s, 0.03 * s, '#26262a', 8); }
  b.add('solid', new THREE.CylinderGeometry(0.11 * s, 0.11 * s, 0.95 * s, 14), white, x, y + 0.2 * s, z, 0, 0, Math.PI / 2);
  b.add('solid', new THREE.SphereGeometry(0.11 * s, 14, 10), white, x + 0.475 * s, y + 0.2 * s, z); b.add('solid', new THREE.ConeGeometry(0.11 * s, 0.34 * s, 14), white, x - 0.645 * s, y + 0.215 * s, z, 0, 0, Math.PI / 2);
  b.box(x + 0.5 * s, y + 0.23 * s, z, 0.08 * s, 0.04 * s, 0.13 * s, '#3f5668'); for (const sd of [-1, 1]) for (let k = 0; k < 7; k++) b.box(x + (-0.3 + k * 0.1) * s, y + 0.22 * s, z + sd * 0.109 * s, 0.035 * s, 0.035 * s, 0.006 * s, '#3f5668');
  b.box(x, y + 0.13 * s, z, 0.95 * s, 0.018 * s, 0.215 * s, tail);
  for (const sd of [-1, 1]) { b.add('solid', new THREE.BoxGeometry(0.28 * s, 0.018 * s, 0.68 * s), white, x - 0.03 * s, y + 0.16 * s, z + sd * 0.42 * s, sd * 0.3); b.add('solid', new THREE.CylinderGeometry(0.038 * s, 0.038 * s, 0.17 * s, 10), C.slate, x + 0.03 * s, y + 0.115 * s, z + sd * 0.32 * s, 0, 0, Math.PI / 2); b.add('solid', new THREE.BoxGeometry(0.13 * s, 0.012 * s, 0.24 * s), white, x - 0.66 * s, y + 0.24 * s, z + sd * 0.13 * s, sd * 0.3); }
  b.add('solid', new THREE.BoxGeometry(0.22 * s, 0.26 * s, 0.018 * s), tail, x - 0.66 * s, y + 0.37 * s, z, 0, 0, 0.42);
}
// Moving parts. Live in the city they're drawn by movers.js; thumbnails and ghosts draw them still.
export function sailParts(b, x, y, z) {
  for (let k = 0; k < 4; k++) { const a = (k * Math.PI) / 2, cx = Math.cos(a) * 0.3, cy = Math.sin(a) * 0.3; b.add('solid', new THREE.BoxGeometry(0.62, 0.016, 0.012), C.wood, x + cx, y + cy, z, 0, 0, a); b.add('solid', new THREE.BoxGeometry(0.46, 0.12, 0.006), C.ivory, x + Math.cos(a) * 0.36 - Math.sin(a) * 0.065, y + Math.sin(a) * 0.36 + Math.cos(a) * 0.065, z, 0, 0, a); }
}
export function carouselTop(b, x, y, z) {
  b.cone(x, y + 0.62, z, 0.92, 0.36, C.terra, 20); b.cyl(x, y + 0.56, z, 0.9, 0.9, 0.07, C.ivory, 20); b.ball(x, y + 1.0, z, 0.06, C.gold, { glow: true, detail: 1 });
  const cols = [C.ivory, C.gold, C.sky, C.pink, C.sage, C.terra];
  for (let k = 0; k < 6; k++) { const a = (k / 6) * Math.PI * 2, px = x + Math.cos(a) * 0.62, pz = z + Math.sin(a) * 0.62; b.cyl(px, y, pz, 0.012, 0.012, 0.58, C.gold, 5); b.box(px, y + 0.2 + (k % 2) * 0.05, pz, 0.08, 0.1, 0.23, cols[k], { ry: -a }); b.ball(px + Math.sin(a) * 0.1, y + 0.32 + (k % 2) * 0.05, pz - Math.cos(a) * 0.1, 0.045, cols[k], { detail: 1 }); }
}

// A token spark: a small star of slim rays around a core.
export function spark(b, x, y, z, s, col = '#e86f4a', glow = true) {
  const kind = glow ? 'glow' : 'solid';
  for (let i = 0; i < 4; i++) b.add(kind, new THREE.BoxGeometry(s * 2, s * 0.15, s * 0.1), col, x, y, z, 0, 0, (i / 4) * Math.PI);
  b.add(kind, new THREE.IcosahedronGeometry(s * 0.2, 1), col, x, y, z);
}

export const BY_ID = Object.fromEntries(CATALOG.map((c) => [c.id, c]));
export const LAND = { start: 6, max: 24, step: 2, cost: (n) => Math.round(2500 * Math.pow(2.1, n) / 100) * 100 };
export const MILESTONES = [1000, 5000, 10000, 20000, 50000, 100000, 250000, 500000, 1000000, 2500000, 5000000, 10000000, 25000000, 50000000, 100000000];

// The long game: ten eras, paced by lifetime tokens.
export const ERAS = [
  { at: 0, name: 'First Light', blurb: 'A hall, a road and a good idea.' },
  { at: 100000, name: 'Market Days', blurb: 'People have started to notice this place.' },
  { at: 500000, name: 'Busy Streets', blurb: 'There is now such a thing as rush hour.' },
  { at: 1000000, name: 'The Growing City', blurb: 'Villas, markets and a very tall tower.' },
  { at: 2500000, name: 'Harbour Age', blurb: 'Boats, flats and botanic gardens.' },
  { at: 5000000, name: 'Golden Years', blurb: 'A big wheel turns over the rooftops.' },
  { at: 10000000, name: 'City of Learning', blurb: 'A university and a campus of busy agents.' },
  { at: 25000000, name: 'Grand Capital', blurb: 'An opera, an exchange and a long archive.' },
  { at: 50000000, name: 'Skyward', blurb: 'The city begins building upward, past the clouds.' },
  { at: 100000000, name: 'The Last Token', blurb: 'A hundred million tokens. Look what you made.' },
];
export const eraIndex = (earned) => { let k = 0; while (k < ERAS.length - 1 && earned >= ERAS[k + 1].at) k++; return k; };

// Buildings can be improved twice. Each level adds people, jobs and joy, and shows on the model.
export const LEVEL_MULT = [1, 1, 1.6, 2.4];
const UPGRADE_PRICE = { 2: 2.5, 3: 6 };
export const canUpgrade = (def) => !def.road && !def.path && !def.fixed && !def.freebie && def.cost >= 400 && !!(def.pop || def.jobs || def.joy);
export const upgradeCost = (def, lvl) => Math.round(def.cost * UPGRADE_PRICE[lvl + 1]);
export const investedIn = (def, lvl = 1) => def.cost + (lvl >= 2 ? upgradeCost(def, 1) : 0) + (lvl >= 3 ? upgradeCost(def, 2) : 0);
